    'HealthCheckDesc'                     => 'Diagnoseer stelselstatus: PHP-weergawe, uitbreidings, lêertoestemmings, databasiskonnektiwiteit, cron-skedule en ekstra aktiverings.',
    'AnnouncementsDesc'                   => 'Stel en bestuur banieraankondigings wat vir alle gebruikers sigbaar is.',
    'RegisterAndUpgradeDesc'              => 'Registreer jou SimpleRisk-installasie, voer \'n intekeningsleutel in of hernu dit, en aktiveer Core/Extra-opgraderings met een klik.',
    'QueueMonitorDesc'                    => 'Inspekteer die agtergrondtaakwaglys: hangende, aan die gang en mislukte take.',
    'ExtrasDesc'                          => 'Aktiveer, deaktiveer en konfigureer SimpleRisk Extras (betaalde byvoegings).',
    'ArtificialIntelligenceExtraDesc'     => 'Die Kunsmatige Intelligensie Ekstra bied verbeterde risiko-analise (insluitend FAIR-assesserings) en aangepaste dokumentasie.',
    'CustomizationExtraDesc'              => 'Die Aanpassing Ekstra maak dit moontlik om verskillende tipes velde by te voeg en te verwyder en dinamies persoonlike bladsysjablone te skep.',
    'NotificationExtraDesc'               => 'Die E-poskennisgewing-ekstra stel SimpleRisk in staat om e-poskennisgewings te stuur wanneer risiko\'s ingedien, gewysig of andersins opgetree word. Hierdie ekstra kan ook as \'n geskeduleerde skrip bygevoeg word om roetine-herinneringe te stuur wanneer risiko\'s gereed is vir \'n bestuursoorsig. In die SimpleRisk Core-produk, sonder hierdie ekstra, word geen kennisgewings buite die instrument self gekommunikeer nie.',
    'VulnerabilityManagementExtraDesc'    => 'Die Kwetsbaarheidsbestuur Ekstra bied kliënte die vermoë om hul SimpleRisk-instansie met Qualys, Tenable.io of Rapid7 Nexpose/InsightVM te integreer en beide bate- en kwesbaarheidsdata in SimpleRisk in te voer. Van daar af kan jy kies watter webwerwe jy wil dek, bepaal watter kwesbaarheidstellings ingevoer moet word en watter kwesbaarhede in risiko\'s omskep word om hulle op te spoor.',
    'IncidentManagementExtraDesc'         => 'Die Incident Management Extra is gebaseer op die NIST 800-61 Computer Security Incident Handling Guide en bied insidentbestuurvermoëns vanuit die SimpleRisk-stelsel.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Hernoem SimpleRisk-terminologie (Risiko, Bate, Raamwerk, ens.) oor die gebruikerskoppelvlak.',
    'RiskConfigurationDesc'               => 'Konfigureer risikotellingreëls: vlakke, aptyt, SLA-drempels en die klassieke / bydraende risikoformules.',
    'RiskAndThreatCatalogDesc'            => 'Handhaaf die katalogus van risiko- en bedreigingswaardes wat in aftreklyste gebruik word.',
    'AddAndRemoveValuesDesc'              => 'Bestuur die aftreklyswaardes vir risikovelde: ligging, bron, kategorie, span, tegnologie en meer.',
    'AssetValuationDesc'                  => 'Konfigureer die batewaardasieskaal en per-bate waardasie-oorskrywings.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Voeg gebruikers by, wysig hulle, deaktiveer hulle en herstel hulle; bestuur wagwoordbeleid.',
    'RoleManagementDesc'                  => 'Definieer rolle en die regte wat elke rol toeken.',
    'TeamManagementDesc'                  => 'Skep en bestuur spanne wat gebruik word vir rekordsigbaarheidsfiltering.',
    'SeparationExtraDesc'                 => 'Die Spangebaseerde Skeidings-Ekstra beperk risikobesigtiging tot slegs die gebruikers wat lede is van die span waaraan die risiko toegeken is. In die SimpleRisk Core-produk, sonder hierdie Ekstra, kan elke gebruiker elke risiko sien.',
    'CustomAuthenticationExtraDesc'       => 'Die Pasgemaakte Verifikasie Ekstra bied ondersteuning vir Active Directory en SAML-verifikasie. In die SimpleRisk Core-produk, sonder hierdie Ekstra, is die enigste opsie om nuwe gebruikers in die SimpleRisk-identiteitsbewaarplek te skep.',
    'EncryptionExtraDesc'                 => 'Die Geënkripteerde Databasis Ekstra genereer \'n ewekansige AES-256-bis enkripsiesleutel en gebruik dit dan om sensitiewe teks te enkripteer voordat dit in die SimpleRisk-databasis ingevoeg word. Dit verhoed dat enigiemand die data kan bekyk of wysig sonder om die SimpleRisk-toepassing direk te gebruik.',
    'OrganizationManagementDesc'          => "Die Organisatoriese Hiërargie Ekstra maak dit moontlik om verskeie Besigheidseenhede te definieer wat enige aantal spanne kan insluit. Gebruikers kan dan aan een of meer spanne onder verskeie Besigheidseenhede toegewys word. Dit beïnvloed 'n gebruiker se vermoë om die spanne, gebruikers en bates waarmee hulle nie geassosieer word nie, te sien en te gebruik.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Risiko\'s van grootmaatverwydering. Gebruik spaarsamig — verwyderings is permanent.',
    'AuditTrailDesc'                      => 'Soek en voer die stelselouditlogboek van gebruikersaksies uit.',
    'ImportExportExtraDesc'               => 'Die Invoer-Uitvoer Ekstra bied die vermoë om data in SimpleRisk in te voer deur velde in \'n CSV-lêer te karteer na velde in die SimpleRisk-databasis. Dit kan gebruik word om ouditresultate vanaf \'n derdeparty-sigblad, kwesbaarheidskanderingsresultate vanaf \'n ander instrument, bates vanaf jou CMDB en meer in te voer. Die Ekstra bied ook die vermoë om CSV-lêers vanaf SimpleRisk uit te voer wat Risiko\'s, Versagtings, Hersienings of \'n Kombinasieverslag van al drie bevat.',
    'JiraExtraDesc'                       => 'Die Jira Integration Extra bied gebruikers die vermoë om bidireksioneel met \'n Jira-instansie te integreer. Dit maak dit moontlik om risiko\'s aan Jira-probleme te koppel, asook om hul data, status en kommentaar te sinkroniseer.',
    'APIExtraDesc'                        => 'Die API Extra laat kliënte toe om \'n RESTful API te gebruik om geskrewe interaksies met ander toepassings te skep om gevorderde outomatisering te verkry en bestaande infrastruktuur te benut.',
    'AdvancedSearchExtraDesc'             => "Die Gevorderde Soek Ekstra brei die funksionaliteit van die boonste balk se soekkassie uit om risiko's te kan vind deur tekssoektogte in risikodata te doen.",
    'AssessmentsExtraDesc'                => 'Die Risikobepaling Ekstra bied gebruikers die vermoë om kontakte te definieer, vrae (insluitend logika) te skep, verskeie vrae met \'n vraelysjabloon saam te stel, vraelyste te skep en dit aan kontakte te stuur, die vraelysresultate te bekyk, risiko\'s op grond van daardie resultate by te voeg, en die resultate oor tyd te vergelyk, ekstern aangepaste assesserings in te voer en uit te voer, en die risikobepaling-ouditspoor te hersien.',
    'ActiveAssessmentsDesc'               => 'Bekyk en bestuur assesserings wat tans aan die gang is.',
    'WorkflowsExtraDesc'                  => 'Die Workflows Extra bied \'n visuele, gebeurtenisgedrewe werkvloei-enjin wat risikobestuursaksies outomatiseer in reaksie op gebeurtenisse binne SimpleRisk. Jy kan werkvloeie ontwerp wat geaktiveer word op veranderinge – soos \'n risiko wat ingedien, opgedateer of hersien word – om goedkeurings te roeteer, werk toe te ken en jou proses aan die gang te hou sonder handmatige ingryping.',

    // Configure Hub - tile descriptions (frameworks category)
    'UCFExtraDesc'                        => 'Die Unified Compliance Framework (UCF) Extra is \'n API-vlak integrasie tussen die Unified Compliance Framework en SimpleRisk. Deur dit te aktiveer, kan jy geselekteerde raamwerke en beheerkarterings direk vanaf UCF invoer.',
    'SCFExtraDesc'                        => "Die Secure Controls Framework (SCF) Extra is 'n direkte integrasie tussen die Secure Controls Framework en SimpleRisk. Dit voer die SCF se katalogus van kontroles en hul kartering oor 'n wye reeks voldoenings- en kuberveiligheidsraamwerke in SimpleRisk se Bestuursfunksionaliteit in, sodat jy die raamwerke wat jy benodig kan aanneem en hul kontroles kan bestuur sonder om dit met die hand te bou.",

